-- A claim's number: given when the claim is opened, the next on its sheet (1, 2, ...) with no
-- gaps and never reused. The sheet keeps the last number it gave; a voided claim loses its number.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
-- The sheet's period numbering from: while set and the sheet's today is on or after it, a claim opened
-- is numbered within the period its date falls in (<period name>-<n>), or X-<n> when in no period;
-- null (blank) means off, and claims take the sheet-wide number.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim numbered within a period: the sequence it counts in ('P<period id>', or 'X' for no period),
-- its place in that sequence (1, 2, ...) and the number as shown; all null for a sheet-wide number.
ALTER TABLE claim ADD COLUMN period_sequence VARCHAR(30);
ALTER TABLE claim ADD COLUMN period_seq_number INT;
ALTER TABLE claim ADD COLUMN period_number VARCHAR(120);
ALTER TABLE claim ADD CONSTRAINT claim_period_number_unique UNIQUE (sheet_id, period_sequence, period_seq_number);
-- A correction names the number of the claim it corrects as shown, a sheet-wide or a period number.
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
-- A place in a period sequence that a claim left when it was re-dated into another period: it is never
-- given again, so the next number of that sequence counts it as taken.
CREATE TABLE claim_retired_number (
    sheet_id VARCHAR(100) NOT NULL,
    period_sequence VARCHAR(30) NOT NULL,
    period_seq_number INT NOT NULL,
    PRIMARY KEY (sheet_id, period_sequence, period_seq_number)
);
package net.officefloor.hq.app.sheet;

import java.util.Collection;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    @Query("select s.lastClaimNumber from Sheet s where s.id = :id")
    int lastClaimNumber(@Param("id") String id);

    /** The last claim number given on any of the sheets. */
    @Query("select coalesce(max(s.lastClaimNumber), 0) from Sheet s where s.id in :ids")
    int lastClaimNumberOf(@Param("ids") Collection<String> ids);

    /** Record the sheet's last claim number given; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query("update Sheet s set s.lastClaimNumber = :n where s.id = :id")
    int setLastClaimNumber(@Param("id") String id, @Param("n") int n);

    /** Take the sheet's next settle batch number; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query("update Sheet s set s.lastSettleBatch = s.lastSettleBatch + 1 where s.id = :id")
    int bumpSettleBatch(@Param("id") String id);

    @Query("select s.lastSettleBatch from Sheet s where s.id = :id")
    Integer lastSettleBatch(@Param("id") String id);

    /** Lock the sheet's row until the transaction ends, so changes checked against the whole sheet take turns. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Sheet lockById(@Param("id") String id);
}

