        this.json = json;
    }

    /** Write the sheet down as it stands now, as at the end of the day given (the today it is leaving). */
    @Transactional
    public void record(String sheetId, LocalDate day) {
        List<Map<String, String>> sheet = select("SHEET", "id = ?", sheetId);
        if (sheet.isEmpty()) {
            return;
